--!nocheck
--[[ v2.39.15_hookauto · hook 自动化 / 3D 索引对账 / 粒子与弹窗修复版
     ============================================================================
     基线：v2.39.12_final（第三轮质检修复版）。本版不改翻译核心（prompt / 解析协议 /
     缓存格式 / 黑名单规则 / hook 实现本体），只做"默认能力 + 漏翻根治 + GUI 修复"。
     逐项改动、原因与验证方式见文末【本版改动明细】，或同目录 v2.39.15_hookauto-更新报告.md。
     ============================================================================

     【一、hook 组自动化（用户要求：翻译器默认就该开 hook）】
       1. 配置页删除两颗手动开关：「文本写入捕获 hook（高风险·关闭即还原）」
          「补间目标改写（随文本写入 hook 自动开启）」。改为一行说明 + 执行器能力/失败提示。
       2. 新增 F.hook_auto_sync()：按「自动翻译（UI 文本）」与「启用翻译」总开关自动
          启用/还原 hook 与补间目标改写；缺能力或启用失败时如实回退并记录原因。
       3. 三处联动：自动翻译开关(L16879)、总开关(L15425)、启动流程(L18711)。
          启动时默认自动启用（不再依赖旧存档里的开关值），失败按 0.8→30s 退避重试
          （缺能力 4 次 / 其它 6 次后回退，并在配置页标红）。
       4. TWEEN_HOOK_ENABLED 默认 false→true；配置迁移判断把 TWEEN_HOOK_ENABLED 也当
          "默认项"排除，旧存档里的 false 不会被误判成玩家配置。

     【二、3D 文本"永久漏翻"根治（真机定位：面板/告示牌文字在眼前却永远英文）】
       根因：3D 文本索引只在注入时建一次，之后靠 DescendantAdded 增量补；注入时就存在、
       但建索引时被跳过/未挂进 3D 容器的实例，以及解析期间流式加载的实例，会永久留在索引外
       → 扫描看不到它们。服务器写入又绕过 __newindex hook，所以开关 hook 也没用。
       实测：把漏掉的 TextLabel 重新挂一次父级（触发增量索引）后 3 秒内全部翻成中文。
       修法：
       1. 新增配置 RECONCILE_INTERVAL=90：每 90 秒把索引标记待重建，扫描循环自动重建索引，
          随后当轮扫描立即处理补进来的文字（30~600 秒可调）。
       2. 「手动扫描当前 UI」现在强制重建 3D 索引再扫 → 遇到漏翻点一下立即修复，不用重注入。

     【三、GUI 粒子特效修复（用户要求：展开/收起全程显示，完全展开后不瞬移）】
       根因：粒子层是 panel 子节点，折叠动画期间 panel.Visible=false → 粒子全程不可见；
       动画结束面板重新可见时，粒子还停在动画期间飘走的位置 → "嘎巴一下瞬移"。
       修法：
       1. 粒子层改为 gui_root 的独立子节点（ZIndex=25，自带 UIScale，尺寸/位置对齐面板）；
          折叠快照克隆时打 FOLD_IGNORE 标记排除，避免出现两份粒子。
       2. 新增 F.sync_particle_layer()：动画期间每帧跟随折叠"纸包"（rig 的位置/尺寸/UIScale），
          动画结束精确落回面板矩形 → 全程可见、完全展开时严丝合缝。
       3. 在 finish_panel_animation / render_panel_fold 末尾、panel 的 Visible /
          AbsolutePosition / AbsoluteSize 变化处同步；面板拖动时粒子跟随。
       4. 粒子层显隐管理：展开或动画中显示、收起后隐藏，避免空层残留。

     【四、卸载确认框排版修复（用户反馈：对话框文字完全被按钮挡住）】
       根因：旧版给 box 套了 apply_dialog_scale（PC 大屏 UIScale≈1.5），但子控件仍按
       "未缩放"的像素坐标写 → 正文与按钮在垂直方向重叠。
       修法：重写 show_unload_confirm()，不再缩放子控件，改逻辑像素 + 内边距精确布局
       （标题 32 / 正文 92 / 按钮 42、间距 12，宽 420 高 226；手机 300×200），
       正文补一行"确认后会立刻卸载当前脚本。"；弹窗 ZIndex 10→120，按钮宽度均分。

     【五、其他】
       1. F.VERSION = "v2.39.15_hookauto"；头部补全本报告。
       2. 未包含"按形状猜玩家名"的聊天过滤：曾试过按 CamelCase/下划线形状跳过，但玩家指出
          Tank_TheRottweiler 这类写法也可能是游戏内 NPC 名 / 地名 / 组织名，会误伤，故最终版
          不按格式猜名字 —— 只保留原有的"当前服务器已确认玩家名"精确匹配（chat_match_name）。

     【明确未改动】翻译 prompt / 输出解析协议 / 缓存格式与落盘节流 / 黑名单规则 /
       hook 内部实现 / 扫描主逻辑 / 聊天管线主体（除上述粒子与弹窗相关外无其它行为变化）。

     【验证】luau-compile 语法通过；建议验证顺序：① 配置页两颗开关消失、hook 自动启用日志；
       ② 卸载确认框三段文字不重叠；③ 展开/收起面板时粒子全程可见、展开完成不跳位；
       ④ 漏翻面板文字等待 ≤90s 自动补翻，或点「手动扫描」立即补翻。
 ]]
--[[ v2.39.12 · 第三轮质检修复版（基于 v2.39.11_qc；原 v2.39.10）
     范围：Phase0 死代码清理 + P0-A/B 输出验收/解析健壮化 + AI 保留协议（[KEEP]/⟦⟧ + 本地资格）
      + 提示词自检 + 聊天 Phase1（消息结构识别、说话人匹配、自身消息、过滤不吞行、无意义门槛、
      负缓存按"说话人+正文"）+ 用户选项（思考模式默认关、第二次重试开关默认关）。
     聊天失败黑名单按用户选择 A：累计 3 次写 blacklist.json 的 chat:<正文>，30 分钟内不再翻。
     不做：聊天内存缓存、历史上下文、术语表、频道区分、A 版正文名掩码、请求格式/restore 点变更。
     逐项改动与验证见 reports/chat-phase1-patch.md、phase2-patch.md；改动处带“★”注释。
]]
--[[ v2.39.10 · 维护者修改版
     ①【界面】API Key 输入恢复掩码：默认显示圆点，聚焦编辑时才显示明文，失焦立即恢复隐藏；
        不再加「显/复」按钮，要复制密钥请点进输入框后全选。
     ②【性能】开关面板的折叠动画不再每次重建整面板克隆：关闭动画结束后整套 rig 停放复用，
        切页 / 主题 / 尺寸变化时才标记 dirty 并重建，反复开关不再反复 clone 数千个实例。
     ③【性能】切页 / 新增控件后的表面刷新只扫描变化的 content 子树，不再每次扫描整个面板
        （之前一次切页会触发两次全量扫描）。
     ④【性能】动画期间的副本同步连接抽成 F.bind_panel_fold_effects，停放复用后重新挂载，
        避免重复连接泄漏。
     ⑤【性能】切页改为隐藏缓存：每个页只构建一次，切走时挪进隐藏 holder，切回时挪回；
        配置变化只标记 dirty，下次访问再重建；单页连接按页登记，重建一页不影响其它页。
     ⑥【正确性】折叠快照停放前记录滚动位置/子树规模，复用前对比；滚动过、历史翻页、
        结构变化时作废重建，避免关闭动画从旧位置开演或缺新行。
]]
--[[ v2.39.9 · 维护者修改版
     ①【hook】安装后做一次"真实拦截"自检：创建一个不挂父级的 TextLabel、写一次纯数字，
        看命中计数是否增加；没增加就还原并如实报错（钩子函数返回合法 ≠ 真的拦得到）。
     ②【hook】同步还原补上「数字模板」：距离/倒计时/计数每变一次就是新原文，
        raw_tr 与主缓存都查不到 → 旧版最后又把英文写回去，屏幕上一闪一闪。
     ③【hook】管线写完后回读一次：数字模板/小快表/样式骨架/小写变体已经写好译文时，
        不再拿原值覆盖（这是"只拦一部分"的直接原因）；比较"调用前/调用后"避免吞掉新写入。
     ④【hook】开关拨动即生效（删掉风险确认弹窗）；启动时按 0.8→30 秒退避重试。
        缺 hook 函数最多试 4 次、其它失败最多 6 次，仍不行就**强制关闭**并保存 false，
        同时在配置页用红字标"暂不支持/上次启用失败"。关闭开关仍等于熔断（还原并核验）。
     ⑤【防闪烁】"放弃抢写"改为 8 秒后自动重试，原文一变立即解除放弃（旧版是整会话永久放弃）。
     ⑥【性能】帧末写回改用 BindToRenderStep(RenderPriority.Last)，排在游戏回调之后
        （同优先级顺序由引擎决定，不保证一定最后；绑定失败会回退 RenderStepped）。
     ⑦【界面】删除密钥输入的「显/复」两颗按钮（连同掩码切换与复制功能），输入框占满整行。
     ⑧【界面】通用输入框加裁剪，长接口地址不再冲出框外。
     ⑨【网络】请求超时按批大小与并发自适应（30~60 秒）；余额/模型查询的基址清洗兼容尾斜杠与 /v1。
     ⑩【能力检测】给 CAP_LIST 加 native/alias/table/report 标记，报告拆成
        "执行器函数 N 项（其中已标记仅探测 M 项）｜表/常量｜原生｜别名"，
        并把逐项明细按分组打印（cap_info），避免"清单 85 项、检测却报 90 项"的误解。
     ⑪【注入顺序】重排为固定六个阶段（日志前缀 [boot]）：
        P1 能力探测（最高优先级，探测完立刻生成 F.plan 降级计划）
        P2 功能模块（队列/扫描/hook/聊天/缓存函数等全部定义完成）
        P3 数据层（缓存上下文/缓存/黑名单/历史/数字模板）—— 从文件末尾提前到 GUI 之前
        P4 GUI 构建（建好但 gui_root.Enabled=false，玩家看不到半成品）
        P5 启动服务（状态页/扫描/hook/聊天/浮窗/向导）
        P6 最后 gui_root.Enabled=true，GUI 才出现
]]
