--[[ v2.39.3 紧急修复（闪烁）：上一版「补间自检失败」的清理会把钩子链搞坏 ——
     钩子还挂着但转发器被清空，游戏的 TweenService:Create 被我们返回 nil，
     UI 补间/重绘全乱 → 整段英文/整段中文反复闪。本版：
       ① 失败清理绝不破坏钩子链：保留转发器、active=false 退化为纯透传；
       ② 还原后用「再触发一次看钩子还会不会被调用」验证，不靠 pcall 返回值；
       ③ 本会话失败后不再自动重试（避免每开一次 hook 多挂一层）；
       ④ 新增防闪烁限流：同一句被反复改回英文 6 次/秒 → 暂停抢写 4~15 秒。
]]
