--[[ v2.39.1 · AI 翻译版（基于 v2.39.0：拆掉本地直转，翻译一律走 AI）
     【一句话】本版只做三件事：**识别**哪些文本需要翻、**拦截/筛选**掉不该翻的、**把该翻的全交给 AI**。
     不做任何"本地把繁体/日文直接改成简体"的替代翻译 —— 译文只可能来自 AI。
     【为什么 v2.37.0 翻不了日文和繁体】
       is_translatable_slow 只有一条判据："文本里出现汉字 → 当它已经是中文 → 跳过不翻"。
         · 繁体中文整句都是汉字 → 全部被跳过；
         · 日文几乎都含汉字     → 同样被跳过（只有纯假名句才出得去）；
         · 聊天管线还有 4 处一模一样的闸门，也一起失效。
     【识别层（F.script_stats：一次遍历同时统计）】
       假名（含半角ｶﾅ）｜谚文 ｜汉字 ｜繁体专用字（1591 对繁→简，只用来"判定"）｜日文专有字形
       （変/売/読/駅/図/団/対/発/覚/実… + 々〆〇，专门解决"纯汉字、没假名"的日文）
     【拦截/筛选规则 —— 命中即"不送 AI"，其余一律交给 AI】
       · 空串 / 低于最小长度（默认 2 字）
       · 纯数字、纯符号、纯 emoji、版本号（v1.2.3）、FPS 数字、rbxasset / URL
       · 已是简体中文（有汉字、无繁体专用字、无日文/韩文信号）且英文 < 3 个字母
       · 已在本脚本译文表里（自己写上去的）、已命中缓存/小快表/数字模板（省请求，不是翻）
       · 玩家手动拉黑的句子
       · 命中后要走 AI 的：英文/其它语言、繁体中文、日文（含纯汉字日文）、韩文、中英混排（英文≥3）
     【交给 AI 时做了什么（全部是提示与校验，不改写译文）】
       ① 【语言方向】写进 UI / 聊天两套系统提示词：目标永远简体，繁体不得原样退回，
          日文按日文词义翻（設定→设置、終了→结束、購入→购买），译文不得残留假名/谚文；
       ② 请求体自动附【本批原文语种（自动检测）】，告诉模型"这批里确实有日文/繁体/韩文"；
       ③ 回写前校验：译文若残留假名/谚文 → 判"没翻干净"，带 repair 提示重试一次；
       ④ 唯一的"本地字符处理"只发生在 AI 已经产出译文之后：把译文里**残留的繁体字**转成简体
          （只换字形，不产生译文）。它不替代 AI，只是收拾模型没转干净的那几个字。
     【和 v2.39.0 的区别】
       · 删除"繁体本地直转简体"整条路（函数 / 调用 / 配置项 / 配置页开关 / 命中计数全删）；
       · 繁体文本现在和英文一样：入队 → 请求 AI → 回写，0 例本地代翻；
       · 状态页与 lang_check() 的计数/输出同步改成"本地命中都是缓存类，译文一律由 AI 产出"。
     【怎么用】
       1) 直接注入本文件；旧配置自动兼容（已删掉的旧开关会被忽略）。
       2) 控制台敲  lang_check()  → 逐条看"会送 AI 翻译 / 跳过不翻"，确认拦截规则符合预期。
       3) 想完全退回 v2.37.0 行为：配置页关掉「翻译繁体 / 日文 / 韩文」。
     【验证】
       · Luau 官方编译器 -O1/-O2 均 0 错误；顶层 local 数不变（182，寄存器预算没增加）；
       · 语言判定 / 筛选 / 残留假名检测 / lang_check 共 58 条离线断言全过；
       · 全文已不存在"本地代翻"相关函数、配置项、开关与命中计数（脚本不再改写译文）。
     【边界】只改语言判定、提示词、请求提示、回写校验；扫描 / hook / 上屏时序 / 界面布局一律没动。
]]
