--[[ v2.36.18 · 补间目标改写（用执行器能力补最后一个洞，且不加任何叠加层）
     上一版用"帧末仲裁（RenderStepped 抢最后一笔）"治好了大部分被游戏覆盖的格子，
     但有一类治不了：**游戏用 TweenService 把文字写回去**。

     为什么治不了：补间是**引擎驱动**的。TweenService 会在之后的每一帧把 `Text` 写成它的
     目标值 —— 这条写入不走 Lua 的 __newindex，还可能落在 RenderStepped 之后，
     于是我们抢到的"本帧最后一笔"会被它盖掉。表现就是"这个词怎么都改不回来 / 一直闪"。

     做法（关键是**不改观感**）：
       hook 住 `TweenService.Create` 这一个 C 闭包，在游戏**创建补间的瞬间**
       把它目标表里的文本值换成译文。动画仍然是游戏自己的动画，只是"终点"变成中文。
       —— 不叠 Drawing、不加第二层文字、不改字号位置，看上去与原生完全一致。

     安全设计（没法真机验证，所以全部按"宁可失效也不出错"来写）：
       ① 只 hook `TweenService.Create`，不碰 __namecall（那会让**每一次**方法调用都过一遍 Lua）；
       ② 目标表里没有文本字段时一律原样转交，零动作；
       ③ 函数体 pcall 全包，出错退回原调用；转发必须用 hookfunction 的**返回值**
          （直接调原函数对象会无限递归 —— sUNC 语义，写错会把游戏所有补间搞崩）；
       ④ 改的是**目标表的副本**，绝不动游戏手上那张表（它可能被复用）；
       ⑤ 装好后**自检一次**：真建一个补间，确认 hook 被调用到；没调用到就自动卸下并如实报错；
       ⑥ 关闭/卸载时先置 active=false（保证只剩透传），再尝试 restorefunction。

     默认关闭（属 hook 组能力），配置页「补间目标改写」一键开关；
     `watch_info()` 里有它的自证：拦截数一直不涨 → 这个游戏不用补间写文字，开关可以关掉。
]]

--[[ v2.36.17 · 补上"服务器/引擎写入"这条管道（执行器能力 + 引擎时序）
     背景：hook __newindex 只看得到 **Lua 侧**的属性写入。服务器复制下来的文字、
           引擎 C++ 内部改的文字**根本不经过 Lua VM** —— 这条边界是真的，绕不过去。
           但"抓不到"≠"补不上"：真正漏的不是 hook，而是下面这几件事。

     ★ 1.【真 bug · 时序】写回是输在"谁后写"，不是输在"谁先发现"
         一帧顺序：Stepped → 物理 → Heartbeat → RenderStepped → **渲染**。
         游戏在 Heartbeat 写完英文，我们的属性回调同步触发、立刻写中文 ——
         看着赢了；但只要游戏在下一次渲染前再写一遍英文，这一帧渲染出来还是英文。
         "上一帧英文、下一帧中文"就是这么来的。
         修法：把还原写回**推迟到 RenderStepped** 统一落笔
         （F.queue_frame_restore / F.flush_frame_restore）。RenderStepped 是渲染前
         最后一个 Lua 回调，所以我们永远是**本帧最后一次写**，渲染出来必然是中文。
         同一帧内完成，没有可见延迟。
     ★ 2.【真 bug · 名额分配】监听名额"先到先得"，被静态文字占死
         旧实现是谁先被翻译谁先占坑。可名额应该给**会变的**文字：一次性的静态标题
         占着名额毫无价值，而每帧刷新的状态面板反而排不上号 → 只能等 1 秒轮询。
         修法：F.try_restore_dynamic 里"这次真的把被改写的文字还原了"就说明这一格是活的，
         立刻给它抢一个名额（F.promotions 计数）；满了由 LRU 踢掉最不活跃的。
         于是监听自动收拢到活跃文字上，静态文字让位给轮询兜底。
     ★ 3.【配置】监听上限默认 3000 → 12000（流畅 4000 / 高级 20000）
         闲置连接零开销（只在属性变化时回调），真正成本是回调里的 Lua 工作 ——
         那部分已经用时间片压平。旧存档若仍是旧默认 3000，会迁移一次并提示。
     ★ 4.【0.4 秒盲区】刚写完译文的格子在扫描里是**整条跳过**的，
         而"刚写完就被服务器改回来"恰是最常见的时序。现在仍做一次 O(1) 即时还原。
     ★ 5.【执行器能力】新增两个控制台自检（都来自 CAP_LIST）：
         · watch_info()   —— 覆盖率：监听数/上限/晋级次数/帧末队列，并**用 getconnections
                             核实引擎侧真的挂着我们的连接**（前几次故障都是"以为挂了、
                             其实已经不在链上"）。
         · roster_check() —— 名册核对：用 getinstances() 拿全部实例，找出"我们本该认识、
                             却完全没登记"的文本对象（文字在 PlayerGui/Workspace/CoreGui
                             之外的情况）。
]]
--[[ v2.36.15 · 卡顿专项（大型游戏"每隔几秒卡一下"）
     症状：小游戏不卡；几十万实例的大游戏里，帧率不算低，但每隔几秒会**顿一下**
           （一帧或连续几帧被顶满），跟帧率抖动不是一回事。

     ★ 结论：这不是"帧数问题"，是**某几帧的 Lua 工作量远超一帧预算**。
       旧代码里所有批量遍历都按"对象个数"让帧（每 200 个 task.wait 一次），
       可单个对象的处理成本差一个数量级；大游戏里 200 个对象往往要 10~25 ms，
       而一帧只有 16.6 ms → 这一帧被顶爆，且会连续顶爆十几到几十帧。
       小游戏里 200 个对象只要 1~2 ms，所以小游戏完全不卡。

     ★ 1.【核心】时间片让帧（F.slice_start / F.slice_due）
         · 扫描 / 建索引 / 新对象批处理 / 兜底轮询，全部改成"每处理几个就查一次
           os.clock()，超出 2 ms 预算就让一帧"。任何一帧的 Lua 工作量被压平，
           与场景大小无关。
         · 每个循环各自持有一份计时（返回值），互不干扰 —— 共享一份计时会让
           几个并发的循环互相把对方的预算清零（一方一帧不让、另一方被饿死）。
         · 涉及：scan_container / build_ui_index / scan_ui_index /
           build_surface_index / scan_workspace_3d / flush_added_batch / 兜底轮询。
     ★ 2.【真 bug】lru_evict 是 O(n·k)，挂在写入热路径上
         · 旧稳态路径是"要淘汰几条，就整表扫几遍找最该淘汰的那一条"；
           而 F.cache_set 每 50 次写入就调用一次 → 缓存满以后每次要淘汰约 50 条
           → 50 × 3 万条 ≈ 150 万次哈希查表，全部压在同一帧里。
         · v2.36.12 把"整表排序一次"改成了"整表扫 N 遍"，复杂度反而从
           O(n log n) 变成了 O(n·k)。
         · 现在：一次线性扫描 + 时间戳分桶，**从最旧的桶开始逐条删、凑够就停**；
           并预留 headroom（多淘汰一点），让下一次淘汰要等几百次写入之后。
         · 同时把 lru_evict 从 F.cache_set 热路径上撤掉，只留在 save_cache 里。
     ★ 3.【性能】is_translatable 加记忆表
         · 旧实现每轮扫描对每个对象都要重跑：is_valid_utf8 + utf8.len + 6 条 :match
           + count_emoji_only（utf8.codes 全串）+ count_cjk（又一遍 utf8.codes）。
         · 现在按字符串记结论，三个相关配置一变就用版本号整体失效。
     ★ 4.【性能】text_context 两处
         · 关键字 tostring():lower() 原本每次调用都新建一个字符串（:lower() 必分配）；
           现在只在配置变化时算一次。
         · 缓存命中原本每次都要沿祖先链**重新校验**（最多 12 层 × 2 次属性读 = 24 次
           C 调用），而同一对象在一次流程里会被连问两次、兜底轮询每秒还问几百个；
           现在 50 ms 内的重复询问直接复用上次结论。
     ★ 5.【性能】面板副本同步原本是永久 30 Hz
         · F.copy_fold_changes 挂在 RenderStepped 上，只要 fold rig 还在就永久跑，
           每个节点 3 次属性读 + 一次 IsDescendantOf，面板几百个控件 × 30 次/秒。
         · 现在只在折叠动画进行中（progress 在 0~1 之间）才同步，并改挂 Heartbeat
           （不再抢渲染前的时间）。
     ★ 6.【性能】内置性能探针默认关闭
         · F.prof_add 原本无条件执行，而被挂在 workspace / PlayerGui / CoreGui 的
           DescendantAdded 上 —— 大游戏加载一次就是几十万次字符串哈希查表。
     ★ 7.【内存】气泡尺寸复核表只增不减
         · SESSION._bubble_fit 只在 billboard 被销毁时才摘条目；assert_left 用完之后
           条目永远留着（强键、换服也不清），2 秒一轮的复核随会话越跑越慢。
         · 现在复核完就从表里摘掉。
     ★ 8.【IO】日志副本单条上限 4 MB → 1 MB；缓存落盘节流 10 秒 → 20 秒。

     未改动：功能、提示词、请求体、界面布局、各档位默认参数一律不动。
]]
--[[ v2.36.14 · 三个新确认的真 bug（由玩家逐行排查指出）
     ★ 1.【内存】F.safe_write（L1440）把每一份写出去的内容**无条件**留在 memory_files 里。
        缓存 / 备份 / 临时文件 / 日志副本四份 MB 级字符串因此被永久钉住
        （实测能到 15~50 MB），而 safe_read 又优先读这张表 —— 磁盘上有、内存里还恒占一份。
        堆变大以后游戏的垃圾回收更频繁更久，卡顿会被放大。
        修法：写盘成功时只给「小文件」留内存副本（≤256 KB，比如配置文件）；
          MB 级的大文件不再留；没有写盘能力时才缓存，且超过 8 MB 也不塞内存。
     ★ 2.【逻辑·真 bug】F.build_surface_index（L7146）在**拿到数据之前**就把 ready 置成 true。
        一旦 Workspace:GetDescendants() 失败（大场景偶发），3D 索引永久为空且永不重试 ——
        表现是"3D 里的告示牌 / 交互提示怎么都不翻，重开才恢复"。
        修法：成功才置 ready；失败记时间戳，60 秒后才允许重试（不会每轮都去啃一次全量）。
     ★ 3.【逻辑·真 bug】新控件批处理（L7357/L7378）的让帧条件永远不成立。
        一批最多 batch_limit=160 个对象，而 yield_every 默认 200 → i % 200 == 0 从不命中，
        等于**一次都没让帧**，160 个新控件全挤在同一帧里处理（三个档位全中：
        流畅档 80/100、均衡档 160/200、高级档 160/200 都是 n < yield_every）。
        修法：步长不超过批大小（n < yield_every 时改成每 n/4 个让一帧）。
     ★ 附：v2.36.12 已按同一份排查修掉的"保存风暴"六项
        （lru_evict 全表排序 / json_encode 全量深拷贝 / lz4 往返自检 / .bak 回读 /
          写盘三连 / 每 10 次读回整个日志），这里不重复说明。
]]

--[[ v2.36.13 · 手机粒子坐标 + 浮窗开关 + 轮询开销（在 v2.36.12 基础上）
     ★ 1.【真 bug】手机端「指针粒子/拖尾」位置不对
        实测反馈：手机上点一下会生成一个粒子，但位置跟手指对不上；鼠标版是对的。
        根因（F.input_position，L4460）：鼠标走 GetMouseLocation()，它返回的是
          **含顶部栏 inset** 的屏幕坐标；手指走 InputObject.Position，它**不含 inset**。
          而下游 F.screen_to_local → F.screen_origin 是按"含 inset"来换算的，
          于是触摸点整体偏掉一个顶部栏高度（常见 36 px，方向偏上）。
        修法：触摸分支补上 GuiService:GetGuiInset()，两种输入落到同一坐标系。
        连带影响：拖拽/滑杆只用相对位移或只用 X 坐标，所以不受影响；
          拖拽的 start 与当前点同时加同一个偏移，位移量不变。
     ★ 2.【逻辑】浮窗被关掉之后，"显示聊天翻译浮窗"开关还显示开着
        根因（L9149 ✕ 按钮）：它只把浮窗 Visible 设成 false、**不动 config 开关**，
          所以配置页那个开关一直是"开"；玩家再点它只会把它关掉，浮窗反而更回不来。
        修法：✕ 就是"关掉这个功能"—— 同时把 config.CHAT_OVERLAY_ENABLED 关掉并
          立刻同步配置页；另外让每 5 秒的浮窗看门狗（L9833）尊重"玩家手动关闭"标记，
          不许再把浮窗自己变回来。
     ★ 3.【性能】兜底轮询 = 卡顿的新主嫌疑（缓存已被实测排除）
        背景：玩家实测"关脚本完全不卡、清空缓存照样卡"，说明病根不在缓存落盘，
          而在"跟游戏里文字对象数量成正比、又反复跑"的那部分。
        嫌疑最大的是兜底轮询：默认每 1 秒抽查 own_write_n/3 个已写格子，
          且**在同一个帧里连续做完**（大游戏一次几百上千个）。而每个格子第一步就调
          F.can_translate_obj → F.text_context，后者要沿祖先链翻最多 12 层、
          做两次 pcall、还建一张小表 —— 可轮询里 90% 以上的格子本来就是
          "我们自己刚写上去、游戏没动"，只需要读一次文字、比一次表就能判定"没事"。
        修法（F.try_restore_dynamic）：把 is_own_write / is_translated_value 这两个
          最便宜又最容易命中的判断提到最前，命中立刻返回；再加上 v2.36.12 的"每 20 个
          让出一帧"。逻辑等价 —— 命中时本来也是返回 true、什么都不做。
      仍在观察（未擅自改动）：整表扫描（每 20 秒）、属性监听回调、每 5 秒的状态页刷新。
        这几个也可能是嫌疑，需要 walk 数据确认后再动。
]]

--[[ v2.36.12 · 缓存落盘与日志副本开销（已实测排除为卡顿主因，改动保留，净收益仍在）
     背景：无论哪个运行时性能档位，大型游戏里每过几秒就"卡一下"；小游戏不卡。
     结论：卡顿来自**三条与"文字总量"成正比的同步工作**，全部跑在主线程同一帧里，
           而运行时性能档位（流畅/均衡/高级）只调"节奏/吞吐"，一个都没碰到它们，
           所以切档位没有效果。改完以后三条都不再是"整份重算"。
     ★ 1. 缓存落盘（F.save_cache）—— 主因
        · 旧路径每次保存：F.json_encode → F.sanitize_deep = **深拷贝整张缓存表**
          + 每个键/每条译文逐字符清洗 UTF-8；再 JSONEncode；再 lz4 压缩 + 压完再解回来
          做一次往返自检；再**读回** 5 MB 主文件写一份 .bak；再写 .tmp + 改名；
          最后把整份明文 JSON 追加进日志副本。
        · 5 MB 级缓存（大游戏几千~几万条）单次就是几百毫秒的同步 CPU + 十几 MB 磁盘 IO，
          而它被"每批译文落一次盘"触发 → 大游戏一进服就是每几秒一次。
        · 现在：两次完整落盘间隔 ≥10 秒（force 立即写，pending 由 30 秒定期保存补写）；
          编码改走"信任路径"（失败自动退回原清洗路径）；lz4 往返自检一个会话只做一次；
          .bak 每 10 次保存复制一次"上一份已编码载荷"（不再读回主文件）。
     ★ 2. 日志副本 cache.journal.ndjson（F.journal_append）
        · 旧路径每 10 次保存就把**整份日志**（几十 MB）读回内存、切成若干条几 MB 的字符串、
          逐条 JSON 解析，只为留下最后一条 —— 这是一次明显的大卡。
        · 现在直接用手上这条完整记录覆盖写；≥4 MB 的载荷不再追加；追加频率降到 1/4。
     ★ 3. LRU 淘汰（F.lru_evict）在缓存满之后的稳态
        · 旧路径只要超出上限就为整张缓存建一份候选数组（3 万条临时 table）再 table.sort，
          只为淘汰超出的那一两条 —— 缓存一满就等于"每次保存都排序 3 万条"。
        · 现在小超量走"逐条挑最该淘汰的那条"（一遍 O(n)、零额外分配），
          只有一次要淘汰很多（玩家调小上限 / 载入超限缓存）才退回整表排序。
     ★ 4. 兜底轮询（每 1 秒）在一帧内抽查 own_write_n/3 个对象
        · 大游戏里 own_write_n 几千 → 一次几百上千个 pcall + 读属性 + 字符串判定挤在一个帧里。
        · 现在每 20 个让出一帧，同样的工作量摊到多帧。
     ★ 5. 逐字节 UTF-8 校验（F.is_valid_utf8）
        · 旧实现每个字节一次 Lua 层函数调用 + 两次 :byte；而 is_translatable /
          count_cjk / count_emoji_only **各自**都调它一次 → 一次"能不能翻"要做 3 遍逐字节扫描。
        · 现在改用引擎原生 utf8.len（C 实现，同一语义），这类判定在扫描/回调/轮询里
          每秒几百上千次，降下来以后每帧的扫描开销也一起降。
     ★ 6. 热点小函数不再每次新建闭包（F.is_own_ui / F.read_prop）
     未改动：功能、提示词、请求体、界面布局、各档位参数一律不动。
]]

--[[ v2.36.11 · runtime performance build
     - Adds three runtime-cost profiles plus a custom mobile-friendly editor.
     - Balanced is the new default; Advanced reproduces the original heavy scan/listener behavior.
     - Coalesces dynamic text refreshes, skips watched properties in fallback polling.
     - Adds PlayerGui text indexing, text-context caching, class filtering and queue category views.
     - Removes stale temporary newcomer connections and marks manual runtime edits as Custom.
]]
--[[ v2.35 · 相对 v2.33 的全部改动（本版为累积版，v2.34 的内容已包含在内）
     【新增：跨执行器能力兼容层】
     - API 探测从 16 项扩到 91 项，覆盖用户提供的 PC/手机全部能力（含 hook/debug/反射/Drawing/压缩/文件系统）
     - 每项独立特性检测 + 降级兜底：缺能力不报错、只降级；状态页如实报告"在用 N 项 / 仅探测 M 项"
     - 取法统一走 getgenv() → _G → 裸全局，修掉旧实现"能力挂在 getgenv 上就探针全灭"的问题
     【新增：存储层增强】
     - lz4 压缩落盘：自描述帧头 + 写前往返自检闸门（自检不过自动退回明文），
       兼容 UNC 双参 / sUNC 单参两套 lz4decompress 签名
     - appendfile 追加式"日志副本"：cache.json 写坏时从最后一条完整记录回收，把损失从"整份"降到"最后一次保存"
     - 缓存/黑名单/历史的单条操作改为可靠触发（信号层），并保留"全部删除"
     【新增：文本写入 hook 层（默认关闭）】
     - 补"扫描 + 属性监听"抓不到的那部分（游戏一次性写入、之后不再改的文字）
     - 可热开关；关闭/卸载时还原元表并**自我核验**；配二次确认 + 一键熔断
     - 注意：它只改 UI 文字外观，不碰武器/移动/伤害/任何网络消息；本脚本从不主动发网络消息
     【新增：特征最小化】
     - 8 个固定属性名（原为 Translator* 前缀）改为每次注入随机 —— 属性是公开可读的，
       游戏一行 GetAttribute 就能确认本脚本存在，那是最直接的特征
     - 日志前缀随机化（原为固定的 [翻译器]）；自识别不再依赖固定文案"译"
     【修复】
     - 说话人归属：旧实现从 "名字: 正文" 里匹配到名字就无条件采信，名字等于本机玩家名时
       直接标成"你"，导致"别人发消息却顶着我"。现在加交叉验证：名字必须能对上一位真实玩家才采信
     - chat_speaker_hint 由"设值→清 nil"改为"保存→恢复"，避免延时回调把提示串给别人的消息
     【按玩家要求取消】
     - 缓存文件自动 GC（玩家已有"全部删除"功能，不需要自动清理）
     【说明】以上不含任何反作弊绕过：不伪造 getrawmetatable 返回值、不隐藏 hook 痕迹、不针对具体反作弊引擎。
]]
--[[ v2.33 · 本轮修复（4 项，只改逻辑，未动网络请求体与提示词）
     ★ 1. 动态监听的 LRU 淘汰方向反了（大游戏里"刚翻好的又变回英文"的一个来源）
         根因：活跃度 dynamic_last_use 只在"游戏改写了这个属性 / 我们回填过一次"时才打点，
               **注册监听时不打点** → 绝大多数从没被游戏动过的监听时间戳都是 0、全部平局；
               而淘汰循环是"从数组尾部往前遍历 + 严格小于"，平局时第一个被扫到的（也就是
               **最新**挂上的那个）会把 cold_t 压到 0，后面同分的都进不来 →
               额度满时踢掉的反而是刚翻好、刚挂上监听的对象，很久以前挂的、早就没用的
               老监听却一直占着名额（与注释写的"淘汰最久没动静的"正好相反）。
         修法：改成按注册顺序**正序**遍历并保留第一个最小值 —— 同分时留下更老的那个（真 LRU）。
               空条目清理顺带改成"先记下标、扫完倒序删" + 惰性建表：这一步是**行为等价的
               改写，不是修 bug** —— 旧的倒序边遍历边删本身是对的（一个都不会漏），
               别把它写成"修了旧 bug"（复核用 Luau 实跑对照过）。
               实测（官方 Luau -O2，2000 组随机差分）：旧实现 1790 次淘汰错对象，
               新实现 0 次错。
     ★ 2. 图标名过滤误杀正常聊天（表现为"聊天气泡偶尔有一条怎么都不翻"）
         根因：is_ui_icon_text 只要"全小写 + 含一个连字符/下划线"就判成 Roblox 图标名，
               于是玩家正常打的整条消息（co-op / e-mail / one-shot / team-up / level-up /
               sign_up / pvp-mode …）会被整条跳过。这条判定不只"扫描聊天窗口"在用 ——
               头顶气泡、游戏自制聊天框也走 process_text_obj → 这里。
         修法：判定顺序改成 ① 精确命中已知图标名（大小写不敏感，只放真实出现过的
               microphone / resize / chat / three-dots 以及多词的 stop-small /
               three-dots-horizontal / microphone-off / voice-chat）→ ② 含大写 → 不是图标名
               → ③ 其余必须"整串只有字母 + 连字符/下划线"（沿用旧实现的约束），
               并且 ≥2 个分隔符，或 长度≥16。
         注意（复核后修正过一次）：第一版漏掉了 ③ 里的"整串只能是字母/分隔符"约束，
               而且名单里塞了 close/leave/settings 这类玩家也可能整句打出来的普通单词 ——
               结果把 "24-7-store"、"counter-strike is fun"、"Close" 这类正常文本也吞了。
               现在这版已修回；已用 28 个用例对照原实现逐个验证：11 处回归全部消除，
               7 个玩家词放行，9 个真图标名（含首字母大写的 Microphone）仍然拦得住。
     ★ 3. 关掉聊天翻译后，浮窗里的"翻译中…"永远不消失
         根因：chat_translation_disable 只清了 chat_pending / chat_inflight，没有清
               SESSION._chat_pending_rows，也没管浮窗里 pending=true 的行 ——
               队列被清空、请求永远不会回来，那几行就一直停在"翻译中…"
               （只有清空浮窗 / 重开浮窗才消失）。
         修法：清掉 pending 登记，并把仍 pending 的行标成"翻译已暂停"后重绘
               （卸载流程里 running 已为 false，不再重绘）。
     ★ 4. 纯中文富文本标签白跑一次请求（还会污染 KV 缓存命中率）
         根因：is_translatable 数英文字母是**按字节**数的 —— <font color="#FF7800">你好</font>
               里的 font/color 就有 ≥3 个字母 → 被判成"中英混排"送去翻译；译文与原文相同，
               本该算失败，却又被 is_whitelist_same 的"含 { } 就放行"救进缓存 →
               每个不同的纯中文富文本标签都白花 1 次请求。
         修法：RichText 保护之后，用"剥掉 {{Tn}} 占位符的正文"再判一次可译性；
               纯中文 / 纯数字 / 纯 emoji 的富文本标签直接不送，真正中英混排的照常送。
         验证：luau-lsp（Roblox 定义 + executor-globals）0 条真实诊断；
               第 1 / 2 / 4 项另用等价实现跑了对照用例（旧行为 vs 新行为逐一比对）。
     本次明确保持现状（评估过但不改）：兜底轮询工作量随会话增长；历史/黑名单"先清脏标记
       再写盘"；3D 扫描整表 GetDescendants（精准覆盖优先）；保存路径的全量深拷贝与
       lru_evict 满配排序（性能，玩家无感）；状态页统计三趟遍历；ClassName 重复读取。
]]
--[[ v2.33 · 第二批修复（按玩家逐条决定；只动相关行，未改动其它布局与逻辑）
     ★ 5. 【功能删除】钉住（pinned）功能整体移除（玩家："这个功能不要了，完全删除"）
         删掉的东西：缓存页每行的「★ 星标」按钮（它其实一直被旁边的「×」完全盖住、
         点不到）、pinned 字段的读写、lru_evict 里的 pinned 保护、两档"钉住已达"告警、
         状态页"缓存条目 N (钉住 M)"里的钉住计数。缓存现在一律按 LRU 自动淘汰
         （先淘汰 LOW 置信度、再淘汰最久没用过的），不存在永不淘汰的条目。
         保留了缓存页「译 / ×」两颗按钮的坐标不动（原来那颗 ★ 的坐标位已空出）。
     ★ 6. 【逻辑】"翻译中…"永久停留：原来只修了"关聊天翻译"这一条路径，
         实际还有两条 —— 关「翻译总开关」、点「还原全部原文（并暂停翻译）」。
         三条现在统一调用新函数 F.chat_pending_abort("翻译已暂停") 收尾浮窗占位行；
         另外重开总开关时补了一次 F.chat_queue_flush（原来只 flush UI 队列，
         卡住的聊天条目要等下一条新消息才会被处理）。
     ★ 7. 【逻辑】缓存页 / 黑名单页的「译」（重新翻译）现在真的会把新译文写回屏幕。
         根因：写回靠 text_objs[key] 找控件，而 retranslate_text 第一步就把 text_objs[text] 清了
         → AI 翻好、缓存也更新，屏幕上的字却不动（那一格显示的正是我们上次写的旧译文：
         定时扫描被 is_translated_value 挡、兜底轮询被 is_own_write 挡）。
         修法：入队前用 last_own_write（记着"往哪一格写过什么译文 + 对应原文"）把控件找回来、
         重新登记；src 传"那一格现在显示的旧译文"，写回前的 source_matches 校验仍然有效
         （游戏若已把那一格换成别的内容，就不会被覆盖）。
     ★ 8. 【逻辑】「× 删除 / 译 重译」对**带数字的文本**现在真的生效。
         根因：除小快表外，"数字模板"也会秒回旧译文（cache_get_dynamic 命中即写回、不问 AI），
         而 cache_remove 只清了小快表、没清模板 → 点完删除下一轮扫描又被旧模板顶回旧译文，
         而且因为不再走 AI，可能长期不自愈。修法：cache_remove 里按 F.num_pattern 反查并清掉模板。
     ★ 9. 【逻辑】聊天翻译失败不再写**全局**黑名单（玩家："聊天翻译写进黑名单合理，
         但不应该是全局黑名单"）。原来聊天失败调 record_failure，而黑名单是全局且与 UI 文本
         共用同一个 key 空间 → 一条聊天句子被拉黑会连带屏蔽同文本的游戏 UI（反之亦然），
         且 ai_refused 是一击拉黑 30 分钟。现在改成聊天本地记账：前两次只是 2 分钟负缓存，
         同一句累计 3 次才停 30 分钟，成功即清零；chat_queue_add 也不再查全局黑名单。
     ★ 10.【逻辑】出站翻译不再把"发出去的英文"登记成"我们自己写的译文"。
         原来 outgoing_write_box 会 mark_translated_value(英文结果) → 别人在聊天里说同一句
         （或游戏 UI 里有同一句）会被 is_translated_value 当成"我们自己写的"整条跳过不翻。
     ★ 11.【UI】手动翻译「📋 复制结果」不再把错误提示当译文复制。
         原来 `manual_last or manual_result.Text` 在翻译失败/还没翻时，会把
         "❌ 请求失败（网络异常或超时）"甚至占位符"（结果会显示在这里）"复制进剪贴板。
     ★ 12.【逻辑】切语境（换模型 / 换题材 / 切用途）时补清兜底轮询的对象表
         （own_write_list / own_write_n / own_write_cursor）—— 原来只清了 last_own_write，
         于是切完语境后轮询在一张全是旧对象的表上空转，slice 还按旧规模算。
     ★ 13.【文案】聊天卡描述改成与实际一致：删掉"使用单独缓存""同一句第二次出现即时生效"
         （聊天译文缓存早已整套移除、不落盘），明确写"不进翻译缓存、同一句再次出现仍会重新请求"。
     ★ 14.【死代码】retranslate_text 里那句清 F.chat_fail_until 从来没生效过
         （那张表是 local、不在 F 上），现在改成真正清聊天本地的负缓存与失败计数 ——
         让"重新翻译"能给聊天文本一次新机会。
]]
--[[ v2.33 · 第三批修复（按玩家逐条决定）
     ★ 15.【翻译判定】"疑似截断"不再重试、不再记账（玩家选择：解决冲突）
         背景：AI 返回后会做一次"像不像没翻完"的检查，其中两条规则会把**正确译文**判成截断：
           · 数字必须原样出现 → 把数字写成中文数词的译文中招（50% OFF → 五折、Top 10 → 前十名）；
           · 译文里出现常见英文词 / 英文词占比 ≥30% → 保留英文专名的译文中招
             （League of Legends → 英雄联盟（League of Legends））。
         旧行为：判截断 → 白重试一次 → 再失败记一次账 → 累计 3 次后整句拉黑 30 分钟
                 （玩家看到的就是"这句话怎么都不翻"）。
         修法：F.looks_truncated 现在多返回一个"原因"：
           · 确凿（placeholder / token / width / cjk_few / empty）→ 仍按原样重试一次；
           · 疑似（digit / english）→ **不重试、不记账**，照常采用但置信度降为 LOW（缓存页标黄）。
         UI 管线与聊天管线都按这个策略走。真不满意还能点缓存页的「译」重新翻（那条路已修好）。
     ★ 16.【逻辑】RichText 关着、但文本里本身就写着成对标签的标签（玩家要求修）
         这类文本走不到"富文本标签保护"那条分支，整串带标签被送去翻译 → 模型多半原样退回 →
         被判"没翻完" → 重试 → 记账 → 3 轮后连这句也拉黑 30 分钟，每轮白花 2 次请求。
         修法：用 "</" 作触发条件（只有真正成对的标签才会出现它，`<PRESS F>` 这类字面文本不命中），
               按"剥掉标签后的可见正文"再判一次可译性：纯中文 / 纯数字 / 纯 emoji 的直接不送。
     ★ 17.【UI】toast 层级 20 → 40（玩家要求修）
         原来低于首次引导向导的遮罩(30)与表单(31) → 向导期间的所有提示被压暗；
         视口高 ≲560px 时会被不透明表单整块盖住、完全看不见。
     ★ 18.【UI】紧凑视口下"译"被"×"压住 4px（玩家要求修）
         缓存页与黑名单页是同一个问题（两处 X 偏移都改了）：移动端按钮 38px、间距 34px，
         X 偏移 -76 → -80；桌面端按钮 24px，取值不变（60）。
     备注（第二批 ★ 8 的说明补充）："数字模板"那条修好之后的行为是 ——
       删除 / 重译一条带数字的文本时，模板也一并删除，它下次出现必须重新走一次 AI，
       然后再重新学习模板。也就是"你点了删除/重译，它就真的重新翻"。
]]
--[[ v2.33 · 第四批修复（按玩家要求：缓存/黑名单的单条操作 + 头顶聊天气泡显示）
     ★ 19.【UI·手机端】缓存页 / 黑名单页的行内按钮适配触屏
         说明：每行右侧本来就各有一颗「译」（这一条重新翻译）和一颗「×」（这一条删除），
         两个页面都有；这次只是把它们在紧凑视口（手机/小平板）下从 38px 放大到 44px
         （触屏推荐最小触控尺寸），两颗间距 8px、右边距 6px，文字区相应收窄到 120px。
         桌面端数值一律不变（按钮 24px、偏移 28/60、文字区减 92px）。
     ★ 20.【UI·聊天气泡】头顶气泡"框比字长一截" + "文字整体偏上"
         ① 框太长（例如译文只有一个"嗨"，框却明显更长）：
            · 原因 A：内边距固定 16px/侧 —— 12px 宽的字会配一个 44px 宽的框（3.67 倍）。
              修法：内边距随文字尺寸收缩，横向 min(16, max(4, 字宽*0.35))、
                    纵向 min(8, max(2, 字高*0.4))。效果："嗨" 44px → 20px（1.67 倍）、
                    "你好" 56px → 40px；长文本上限不变（仍是 16/8），300px 的译文框宽不变。
            · 原因 B：游戏的背景框大多是按父级拉伸（Scale）定义的，旧代码遇到这种框
              **直接跳过不改** → 框一直保持按**英文长句**算出来的大小。
              修法：像素定义的背景照旧（放大缩小都行）；纯 Scale 背景改为"只收不放" ——
                    算出来比当前小就按像素写进去，比当前大就不碰；都失败再退回"改父级"。
         ② 文字偏上：旧代码只把文字对到它**自己父级**的中心，而游戏常把文字放在额外一层
            容器里（那一层的中心 ≠ 可见气泡框的中心，框底部可能还给头像/尾巴留了位置）→ 看着就偏上。
            修法：改成对到**背景的中心** —— 同一父级时用 0.5/0.5；跨层时按绝对坐标换算
            （带范围合法性保护：算出来不在父级范围内就退回 0.5/0.5，防止气泡未渲染时坐标不可靠）。
            另外显式设置 TextXAlignment / TextYAlignment = Center、TextTruncate = None，
            避免文字在标签内部又被顶到上边或被截掉尾巴。
]]
--[[ v2.33 · 第五批新增（按玩家要求：文件路径显示与复制 + 手改译文）
     ★ 21.【UI】缓存页 / 黑名单页各加一张"文件位置"卡片：显示数据文件的当前路径 + 「复制路径」
         · 路径取自 _G.FILE_CACHE / _G.FILE_BLACK；能拿到执行器工作目录（getworkspace）时显示绝对路径，
           拿不到就显示相对路径（默认 RobloxTranslatorCache/…）。
         · 「复制路径」在**点击时**才取值 → 切了「按游戏隔离配置」（缓存文件名会变）之后，
           复制的也永远是最新路径。
         · 手机端：按钮 44px 高、所在行 50px 高；路径标签超长自动截断（复制到的是完整路径）。
         · 复用 F.copy_text：有剪贴板权限就直接复制并提示"已复制到剪贴板"，
           没有权限就弹出可长按选中的文本框兜底。
     ★ 22.【功能】缓存页每行新增「改」按钮 —— 直接修改**译文**（原文一个字都不动）
         · 打开脚本自带的输入对话框（复用 F.text_dialog，尺寸按视口自适应、手机端可点、支持换行）。
         · 保存后：① 写进缓存（置信度 HIGH、标 manual=true → 列表里显示 ✏ 标记，一眼区分 AI 翻的）；
           ② 登记小快表与数字模板（下次出现秒回玩家改的这条）；③ 清掉该句的失败记录与黑名单
           （既然玩家能给出译文，就不该再挡着它）；④ **立刻写回屏幕上所有显示这句原文的控件**。
         · 校验：空译文、或与原文一模一样 → 不保存、对话框留着继续改。
         · 说明：手改的译文同样参与 LRU 淘汰（钉住功能已按你的要求删除），
           被淘汰后这句会重新交给 AI —— 想长期保留就避免让它长期不被使用。
     ★ 附带重构：把"把当前显示这句原文的控件重新登记进 text_objs"抽成 F.retrack_displayed，
       供「重新翻译」和「改译文」共用（行为与原实现一致，未改语义）。
]]
--[[ Roblox 翻译脚本 v2.25 · 提示词质量、题材理解与队列修复（最新）
     ★ 玩家反馈 1："我没有勾选扫描 CoreGui，却还是翻译了游戏原本自带的按钮 UI，之前是没有这种情况的"
        根因：v2.16 加的 **CoreGui 新对象监听完全不看开关** —— 只要 CoreGui 里冒出新控件就翻
        （很多游戏的按钮/HUD 就在 CoreGui 里）。同一个函数还被挂在 workspace 上，
        于是「扫描 3D 文本」关掉也一样没用。
        修法：拆成两个监听，各看各的开关（CoreGui → SCAN_CORE_GUI，3D → SCAN_WORKSPACE_3D），
              而且是**事件发生时判断**，所以你随时开关立刻生效，不用重注入。
     ★ 玩家反馈 2："我们脚本自带的悬浮聊天框，它下面那行原文本也被翻译了"
        根因：**新对象监听没排除我们自己的界面** —— 浮窗里的标签一创建就被挂上"临时监听"，
        我们往标签里写"原文"时，监听立刻把缓存里的中文写回去 → 原文行变成中文。
        （主面板和浮窗都挂在 gui_root 下，而扫描器有排除、监听器没有 → 只有监听这条路漏。）
        修法：新增 F.is_own_ui(obj)（是不是我们自己界面里的控件），在**5 个入口**都拦一道：
              新对象监听、批处理、process_text_obj 总入口、缓存秒回、动态/临时监听。
              也就是说：面板、浮窗、悬浮球、弹窗里的任何文字，这辈子都不会再被翻译。
        实机验证：往脚本自己的界面里插一个英文标签 → 10 秒后仍是英文，
                  而且请求日志里**没有任何一条**包含它（连送都没送出去）。
     ★ 玩家反馈 3："你说你查询成功了，但我这边还是失败 / 这查的压根就不对"
        做了三件事让它"可自证"：
          · 时间改成**本地时区**（Roblox 的 os.date 是 UTC，显示出来会比本地早 8 小时 → 看着像没查对）；
          · 结果里直接标出**用的是哪个 Key**（尾号 6 位），方便确认是不是查到了别的账号；
          · 出错时把**接口路径 + HTTP 状态 + 返回片段**都写出来（例如 HTTP 401（/user/balance）：…）。
     验证：luau-compile 0 错误；模拟环境 168 项断言全过（本次新增 5 条）；
           反向验证：拿 v2.22 跑同一套新用例，正好失败 2 条 ——
             "自己界面里的文字不会被翻译"        → 实际 译:Settings
             "关掉后，CoreGui 新对象保持原文"    → 实际 译:CORE GUI PROBE BBBB
]]
--[[ Roblox 翻译脚本 v2.22 · 修「关掉开关还在翻」+ 两个功能回归
     ★ 玩家反馈（截图）："会把原文翻译了，我明明没有勾选翻译游戏本体的 ui，所以这是什么情况？
        之前没有这种情况的，现在就有了。"
        查清了，是**三个自动入口没看这个开关**（不是开关坏了）：
          [1] 启动扫描：注入瞬间无条件扫一遍完整 UI；
          [2] 新对象监听：游戏新建的控件（PlayerGui / 3D / CoreGui）一到就翻；
          [3] 缓存秒回：try_restore_dynamic —— 控制台/面板被游戏改写时，把缓存里的中文"秒写回"，
              这条最像"开关失效"，因为它连请求都不发、关掉开关也照样把中文塞回去。
        修法（v2.22 的 4 道闸门）：
          ① F.process_text_obj 的"游戏本体 UI/3D"路径：开关关了就 return
             （放在聊天分支**之后**，所以聊天不受影响）；
          ② F.try_restore_dynamic：开关关了不再把缓存中文写回游戏 UI（聊天类豁免）；
          ③ 启动扫描加 config.AUTO_TRANSLATE 判断；定时扫描本来就有；
          ④ 排队中的译文写回时也再查一次（开关关掉后，迟到的一律不落）。
        例外：玩家自己点「手动扫描」= 显式操作 → 临时放行，并给它 90 秒写回窗口。
        聊天翻译独立于这个开关，仍然照常（有它自己的开关）。
        反向验证：拿 v2.21 跑同一套新用例，正好失败 2 条 ——
          "关掉开关后，新建的英文 UI 保持原文" → 实际 译:PLEASE DO NOT TRANSLATE 8842
          "缓存里的中文不会被重新写回游戏 UI"    → 实际 译:Settings
        实机（真机 + 真 Key）A/B：开关开着新建的 TRANSLATE ME 1111 → 翻译我 1111；
          关掉开关后新建的 PLEASE DO NOT TRANSLATE 8842 → 一直是英文。
     ★ 玩家纠正："什么叫你都删了，我是说让你修复后面那两个，缓存的那个诊断才是让你删掉的"
        上版是我理解错了。本版把这两样**恢复并修好**（诊断卡片依旧保持删除）：
          · 「💰 查询余额」：按官方文档 GET /user/balance，列出每个币种（total / 赠金 / 充值）、
            账号是否可用，并标上查询时间（免得把上一次的数字当成现在的）。
            以前只显示 balance_infos 的第一条。
          · 「显示 token / KV 缓存统计」：按官方 usage 字段（prompt_tokens / completion_tokens /
            prompt_cache_hit_tokens / prompt_cache_miss_tokens / prompt_tokens_details.cached_tokens）
            **按会话累计**：请求数、输入/输出 token、KV 缓存命中率；状态页还显示"最近一次"明细。
            以前只显示最近一次、而且开关关着时也没人记账。
        实机结果：余额显示 "CNY 1.79（赠金 0.00 / 充值 1.79）｜账号可用：是｜11:58:04 查询"；
          token 统计显示"本次会话：请求 2 次 / 累计 token：输入 1173（KV 缓存命中 768，65%）/ 输出 20"。
     验证：luau-compile 0 错误；模拟环境 163 项断言全过（含本次新增 10 条）；
           分析器 SameLineStatement / LocalUnused / ImplicitReturn 全为 0。
]]
--[[ Roblox 翻译脚本 v2.21 · 注入器报错核对 + 按玩家要求精简
     ★ 玩家反馈 1（截图）：缓存页那张"诊断：这个词为什么没命中缓存"卡片 ——
        "说是在上面输入，结果连个输入框都没有，应该是被那个红色按钮挡住了"。
        处理：整张诊断卡片（含两个搜索框 + 复制按钮 + 背后的扫描记录机制）**整块删除**，
        红色"清空全部缓存"按钮不再压着任何东西。
     ★ 玩家反馈 2（截图）："这个查询功能是错的" = 账号卡里的「💰 查询余额」→ 整个按钮删除；
        "显示 token 这个功能也没有用" = 「显示 token / KV 缓存统计」→ 开关 + 状态页统计块删除。
     ★ 玩家反馈 3："为什么每次更改都会改一遍 UI 的布局"
        本版对界面**只删不加**：删掉上面两个按钮/开关和那张诊断卡片，其它位置一个像素没动。
     ★ 玩家反馈 4（注入器报错附件 41 条）：逐条核对，只有 2 条指向真代码 ——
        [真 bug] UnknownGlobal 'current_tab_name'（3545/3577 行）：
            current_tab_name 声明在文件后半段的 UI 代码里，而 F.scan_all 定义在它前面。
            Lua 的 local 只对"声明之后"生效 → F.scan_all 里那两处读到的其实是全局变量（永远 nil），
            "手动扫描完立刻刷新状态页"从来没生效过。→ 已改成前置声明（和 gui_root 一个位置）。
        [风格] SameLineStatement ×34（同一行写两条语句）→ 已全部补上分号，语义不变。
        其余 5 条：UnknownGlobal 'syn'（Synapse 探测惯用写法，故意保留）、
        ImplicitReturn ×1（校验函数失败时补了显式 return nil）。
     ★ 顺手清掉的无用代码（玩家要的"没有空壳"）：
        · SESSION._diag 诊断计数器 —— 诊断卡片删了以后 11 处计数没有第二个读者，全删
        · last_usage（"显示 token"删掉后没人读）· F.recent_tr_count（定义后从未被调用）
        · F.try_restore_dynamic 分支里重复声明的 local rec
        · 面板标题的版本号一直写着 v2.15（改了没同步）→ 现在跟文件名一致 v2.21
        · 黑名单页文案还在说"去缓存页 → 诊断查"（那页已经没了）→ 改成"用搜索框搜"
        · 账号卡文案"（点下面两个按钮查询）"（其实只剩一个）→ 改成"（点下面的按钮查询）"
     ★ 真机测试（Studio 实机 + 真 Key）里抓到并修掉的一个老 bug：
        Roblox 的 UIListLayout **默认按"控件名字"排序**，而本脚本所有控件的名字都是随机的
        （防检测设计）→ 7 个页签的顺序每次注入都不一样（实测抓到：历史/状态/配置/缓存/黑名单/
        快捷键/外观），主题色圆点、黑名单/缓存/历史列表的行顺序同样被乱排（明明按时间排好了）。
        修法：这几个布局显式写 SortOrder = LayoutOrder，并给每行按显示顺序编号。
        **没有挪动任何控件的位置或大小**，只是把顺序恢复成设计的样子。
     验证：luau-compile 0 错误；模拟环境 153 项断言全过（完整 + 精简注入器两套，各连跑 3 次）；
           分析器 SameLineStatement / LocalUnused / ImplicitReturn 全部归零（只剩 Roblox 全局名噪声）。
]]
--[[ Roblox 翻译脚本 v2.20 · 出站方向纠错 + 浮窗布局版
     ★ 玩家反馈 1："我把'听不懂'想翻成英文，结果给我翻成'我不明白'"
       代码里两层原因：
         (a) 模型偶尔不照方向来，给个中文近义词；
         (b) 我加的"方向不对就重试"用了 outgoing_en_hard 这个新种类，
             **提示词模块没认出来** → 重试发出去的其实是"普通 UI 提示词（翻成中文）" → 又是中文。
       修法：提示词模块认得 hard 种类；出站翻译改成两趟（正常 → 硬性要求），
             两次都不行就明确提示失败，绝不把中文塞回输入框。
     ★ 玩家反馈 2："翻到底了，输入栏还挡着几条消息"
       原因：① 行高估算把中文按英文宽度算（中文一字顶两字母宽）→ 行算矮、内容被裁；
             ② 底部给输入栏留的位置偏小（70px）；③ 列表没有底部内边距；
             ④ 每次重画时把"非布局对象"全删 → 连内边距也被自己删掉。
       修法：行高按半角宽度单位（汉字=2、英文=1）重算；底部 70→84px；
             列表加 6px 底部内边距（重画时不再误删）；新增"自动滚到底部"
             （新消息自动跟随，玩家自己往上翻历史时不打断）。
     验证：luau-compile 0 错误；模拟环境 154 项断言全过（完整 + 精简注入器两套，连跑 3 次稳定）。
]]
--[[ Roblox 翻译脚本 v2.19 · 浮窗自愈版
     ★ 玩家反馈："显示聊天翻译浮窗 这个功能会延迟显示……玩到后面甚至直接消失了，关掉重开也显示不出来"
     代码里确实有两个 bug：
     [1] 浮窗以前是"收到第一条聊天消息"时顺手创建的 → 没聊天就永远不显示；关了再开也出不来
         （那一刻没有新消息，就没人去建它）。
         现在：注入后 0.6 秒直接建出来并显示；打开开关时立刻建出来并显示（带"等待聊天消息…"提示）。
     [2] 浮窗挂在 gui_root 下，而大型游戏会清空/重建 CoreGui（或执行器换容器）→
         整个界面变成孤儿：面板和浮窗都看不见，怎么开关都不回来。
         现在：新增看门狗（每 5 秒）——容器没了就重新挂回去；浮窗没了/变孤儿就重建并显示。
     ★ v2.18 内容（同批交付）：
       · 历史上限 200 → 2000（可调 20~20000）
       · 回填提速：新对象批处理 0.25→0.1 秒、"先建后填字"防抖 0.6→0.35 秒、兜底轮询周期 1.5→约 1 秒
       · 查缓存时顺手试一次小写键（CUFFED / Cuffed 不再各问一次 AI）
       · 玩家指出"缓存只有 200 多 KB 根本没装满"→ 已更正：延迟不是淘汰造成的，而是回填路径固有耗时
     验证：luau-compile 0 错误；模拟环境 149 项断言全过（完整 + 精简注入器两套）。
]]
--[[ Roblox 翻译脚本 v2.17 · 小快表版
     ★ 本版针对玩家反馈："翻译已经翻译过的东西还是有延迟，只不过没那么大"
     先把剩余的延迟拆清楚（只有最后一种要问 AI）：
       · 缓存命中 + 监听在（游戏把中文改回英文）… 50~66 毫秒，0 请求
       · 新对象出现（新建对象批处理 ≤0.25 秒）……… ~0.3 秒，0 请求
       · 对象先建、文字后填（临时监听 + 0.6 秒防抖）… ~0.9 秒，0 请求
       · 兜底轮询轮到它（第三道保险）………………… ≤1.5 秒，0 请求
       · 缓存条目被 LRU 挤掉 → 重新问一次 AI ………… 1.5~3 秒，要请求
     大游戏字符串多，5MB 缓存装满后久一点的词会被挤掉，玩家感觉到的"还有延迟"基本就是最后一条。
     ★ 本版改动：新增"小快表"
       · 专门记最近翻过的 800 条（键 → 译文），**不受 5MB 预算与 LRU 淘汰影响**（几十 KB 内存）
       · 命中即瞬间写回、0 请求；扫描/动态回填/兜底轮询三个入口都会查它，聊天译文也记进去
       · 诊断面板新增一行"小快表（最近翻过的）：N 条"
     ★ 另外：玩家自己发现天上那块告示牌是"游戏把每个字母做成独立小方块拼的"
       （不是文字层能整体读取的东西），按他的意思本版没有为它做特殊处理。
     验证：luau-compile 0 错误；模拟环境 142 项断言全过（完整 + 精简注入器两套，连跑 3 次稳定）。
]]
--[[ Roblox 翻译脚本 v2.16 · 告示牌与浮窗版
     ★ 本版针对你这两条反馈：
     [1] "挂在天上的告示牌：S C H E D U L E D 半中半英、翻不了"
         原因：这是"字母之间插空格"的样式文本，AI 会当成装饰标题原样退回，
         失败 3 次后进黑名单 → 永远翻不出来（同一块牌子上的中文条目就翻了）。
         修法：送翻译前先折叠成正常单词（S C H E D U L E D → SCHEDULED）。
         真机实测：2.73 秒变中文（已安排）；普通单词对照 0.20 秒（走缓存）。
     [2] "你说会被拉进黑名单，但我在黑名单里搜不到"
         原因（代码）：黑名单**页面**只列 fail_count ≥ 3 或手动加入的条目；
         失败 1~2 次的记录在表里但**不显示**，表现就是"每次出现都重试一次 AI、结果还是英文"。
         现在：诊断面板会显示真实失败次数（含"未达拉黑门槛"说明），黑名单页也加了说明文字。
     [3] 浮窗（玩家反馈：不能滚动 / 原文离译文太远 / 换行不智能）
         · 列表改成 ScrollingFrame：支持滚轮上下滚 + 手指拖动，长内容不再被裁
         · 一条消息 = 一个"行容器"：译文本 + 紧贴其下的原文（间距 1px）
         · 宽度按浮窗宽度精确计算（不再读可能过期的 AbsoluteSize → 不再出现大空隙）
     [4] 自我翻译防护（真机截图反复抓到"原文行是中文"）：
         · 新增汉字计数：含 ≥3 个汉字就视为"已经是中文"，三条管线入口全部拦下
         · 聊天行"玩家名 正文"（没冒号）也会把名字剥掉再判定
         · 浮窗唯一入口再加一道：原文是中文就不进浮窗
     [5] 新增"扫描记录"诊断（回答"总不能说是没识别到吧"）：
         扫描器实际看到过的每条文字都留档（文字 + 去向 + 控件路径），
         搜不到 = 它根本不是文字控件（图片/贴图，或被游戏拆成"一个字母一个控件"）。
     验证：luau-compile 0 错误；模拟环境 137 项断言全过（完整 + 精简注入器两套）。
]]
--[[ Roblox 翻译脚本 v2.15 · 大游戏专项（缓存/回填这次是真找到两个 bug）
     ★ 本轮在代码里挖到并修掉的两个真 bug（都有测试/真机证据）：
     [1] 整批请求失败时**没走兜底**：网络异常 / 429 限流 / 额度不足时，
         chat_queue_flush 直接 return —— 那条文字既没记失败、也没转 UI 通道，就一直挂着英文。
         现在按条处理：记失败 + 转 UI 通道兜底（测试里 fallback 计数 0 → 1，最终翻好）。
     [2] 兜底轮询的"切片"太小：每轮只抽查 250 个对象 → 大游戏（1340 个对象）要十几~二十秒
         才轮到一遍，玩家看到的就是"又要等几十秒"。
         现在按总量自适应：每 0.5 秒一轮、每轮约 1/3，整轮 ≈1.5 秒。
     ★ 针对"反复出现的词"的关键改动：
     [3] 监听名额改成"按活跃度淘汰"：以前满了淘汰"挂得最早的"，反复出现的词很容易被淘汰；
         现在淘汰"最久没动静的" → 反复出现的词永远留着监听，游戏一改回来就立刻改回中文。
     [4] 监听上限 400 → 5000（配置页可调）。
     [5] 3D/UI 嵌套查找深度 8 → 12 层；CoreGui 也监听新对象（有些大型游戏把 HUD 做在 CoreGui 里）。
