     [7] 失败负缓存顺序修正：先查译文、再看失败标记（避免"先失败后成功"的句子被挡 2 分钟）。
     [8] 面板标题显示版本号（v2.15）；缓存页新增"诊断"面板：输入一个词，直接列出它在
         主缓存 / 聊天缓存 / 数字模板 / 黑名单 / 失败负缓存 里的状态，以及监听数、本轮回填次数。
     真机实测（v2.15）：
       · 先建空对象、2 秒后填字：CUFFED 3.15 秒、Press E to Interact 3.28 秒自动变中文
       · 游戏把文字改回英文：50~66 毫秒恢复
     验证：luau-compile 0 错误；模拟环境 131 项断言全过（完整 + 精简注入器两套），重复跑 3 次稳定。
