--[[ Roblox 翻译脚本 v2.14 · 先建后填字修复版（"等几十秒"的真凶）
     ★ 你问"是不是 AI 的原因"——不是。代码层面查出来的真相：
     1) 新对象出现 → 脚本 0.25 秒内就会去读它的文字（新建对象批处理）
     2) 但很多对象（CUFFED 挂牌、Press E to Interact 提示）是"**先创建、下一帧才填字**"，
        这时读到的是空字符串
     3) 代码里遇到空文本直接 return —— **既没翻译、也没挂任何监听**
     4) 于是只能等下一轮整表扫描（默认 30 秒）才被看见 → 你看到的"要过好几十秒"
     缓存命中本来就是纯本地查表（不联网、不等 AI、不审核），所以"慢"跟 AI 无关，
     真正的问题是"没人去看它"。
     ★ 本版改动：
     [1] 新增"临时监听"：刚出现的对象（TextLabel/TextButton/TextBox/ProximityPrompt）
         会被挂上 20 秒的监听，这期间只要被填上文字就立刻按正常流程处理
         （含 0.6 秒防抖，逐字打出来的字不会一条条乱翻）。
         真机实测：先建空对象 → 2 秒后填 "CUFFED" → 3.55 秒变中文；
                   填 "Press E to Interact" → 3.52 秒变中文。
     [2] 手动扫描：新增"开始扫描"提示 + 状态页实时进度（已看 N 个对象）+
         结束后立刻刷新状态页（以前只显示"扫描进行中"，要等自动刷新才知道结果）。
     [3] 缓存页 / 黑名单页新增**关键词搜索**（输入即可，不必完整匹配），
         命中的片段自动标绿（RichText）。
     验证：luau-compile 0 错误；模拟环境 123 项断言全过（完整 + 精简注入器两套）；
           真机：先建后填字 3.5 秒左右自动翻译、缓存跨注入 0 新请求。
]]
--[[ Roblox 翻译脚本 v2.13 · 反复出现的文字秒回版
     ★ 本版解决你报的："同一个词一直在出现，但每次都要等很久才被翻译上，缓存根本没用"
     先说结论（真机量的）：
       · 磁盘缓存**一直在正常工作**：连续两次注入，累计翻译请求仍然是 1 次（全部命中缓存）
       · 慢的不是"缓存没命中"，而是"**命中之后没能立刻显示**"——
         以前只有 30 秒一轮的整表扫描才会把缓存里的中文写回屏幕，
         而且"即时回填监听"上限只有 400 个对象，大游戏里早就满了 → 后面的文字根本没人盯。
     本版改动：
     [1] 即时回填监听：上限 400 → 3000（新配置项 WATCH_MAX，配置页可调），
         满了不再"拒绝新对象"，而是淘汰最早挂的那个（LRU）；对象销毁时自动断开监听（防内存泄漏）。
     [2] 新增"兜底轮询"：每 1.5 秒抽查一批（每轮 250 个）我们写过的对象，
         发现被游戏改回英文就立刻用缓存补回中文 —— 就算监听没挂上/被淘汰，最多 1.5 秒，
         而不是 30 秒。里面的每次成功回填都有计数（SESSION._recheck_restores），方便排查。
     [3] 回填逻辑抽成一份 F.try_restore_dynamic：缓存 → 数字模板 → 聊天缓存 → "上次写在这格的译文"
         四重兜底，并且加了一道"大小写不同也算同一句"的宽松查找。
     真机实测：
       · 游戏每 0.5 秒把面板改回英文，采样 14 次里 13 次是中文（另一帧是正在写的瞬间）
       · 连续 6 次"改回英文 → 恢复中文"的耗时：50 / 50 / 50 / 66 / 66 / 50 毫秒（≈瞬间）
       · 跨注入缓存：第一次注入 1 次请求，第二次注入累计仍是 1 次（0 新请求）
     验证：luau-compile 0 错误；模拟环境 111 项断言全过（完整 + 精简注入器两套）。
]]
--[[ Roblox 翻译脚本 v2.12 · 浮窗换行 + 只显示玩家消息版
