         · 缓存被淘汰后也能用"上次写在这一格的译文 + 它对应的原文"立刻顶回去（不重新请求 AI）
         · 3D 里"运行时才出现"的文字（互动提示/状态板）也会马上处理，不用等 30 秒整表扫描
     验证：luau-compile 0 错误；模拟环境 108 项断言全过（完整 + 精简注入器两套）；
           真机：长句折行、动态文字回填、交互提示回填、自动翻译发送 均已实测。
