--[[ Roblox 翻译脚本 v2.9 · 拖动修复 + 浮窗出站翻译版
     ★ 本版改动（全部真机实测过）：
     [1] 修复（玩家反馈：拖动延迟 / 跟鼠标完全对不上 / 会瞬移）
         根因：Roblox 里"鼠标输入坐标"和"GUI 的 AbsolutePosition"差了整整一个顶栏高度
         （GuiInset=58；IgnoreGuiInset=true 的屏幕Gui 原点在 y=-58）。
         老写法用"输入坐标 − AbsolutePosition"当抓取偏移 → 一按下就跳 58 像素、
         之后一直偏在鼠标上方 58 像素。
         现在改成"增量式拖动"：只记按下时的鼠标位置 + 窗口在父容器里的真实位置，
         之后按鼠标位移量搬窗口，两套坐标的固定偏差自动抵消。
         真机实测：鼠标 +200/+100 → 悬浮按钮正好 +200/+100；浮窗 +150/+100 → 正好 +150/+100。
     [2] 修复：面板/浮窗的标题栏原来用 Frame+Active 收拖动输入，真机里收不到
         → 换成 TextButton（按钮一定能收到），外观不变。
     [3] 修复：拖动刷新率下限从 5 提到 24（低于这个会明显"跟不上手"），默认 60。
     [4] 新增（按你的要求）：浮窗自带输入框 + 出站翻译
         · 在浮窗底部输入框里打中文 → 按快捷键（默认 右Shift+Y）或点「译」→ 变英文
         · 打英文 → 同一个键变中文（方向自动判断，不用记两套快捷键）
         · 「发」= 直接发到游戏聊天（走游戏自己的过滤，不自动发）
         · 结果进本地缓存，同一句再翻是秒出，不重复花额度
