         · 聊天回调用 message.TextSource.Name
         · 聊天窗口那种"<font>玩家名:</font> 正文"的整行会拆出名字
         · 玩家气泡/名牌按归属角色反查玩家名
         · 自己说的话显示"你"
     [6] 修复（真机截图发现）：浮窗里把聊天行的富文本源码（<font family='rbxasset...'>）
         原样显示出来，一大串看不懂的东西。现在只把"正文"送去翻译、只替换正文，
         玩家名与颜色标记原样保留，浮窗里显示的也是干净文字。
     [7] 修复：以 / 开头的游戏指令（例如 /dang 106 bced）现在也会翻译（提示词里写明了规则）。
     [8] 修复：浮窗输入行的「发」按钮原来有一半跑到浮窗外面被裁掉（真机截图发现）。
