--[[ Roblox 翻译脚本 v2.8 · 嵌套面板 + 浮窗自定义版
     ★ 本版改动（都有真机证据，不是"看着改了"）：
     [1] 修复（真机截图：SCP 类服务器整块告警屏一个字都没翻）
         原判定"3D 面板文字"只认控件的**直接父级**是不是 SurfaceGui / BillboardGui；
         而游戏普遍写成 SurfaceGui → Frame → TextLabel，于是整块屏被跳过
         （只有极少数直接挂在容器下的文本碰巧被翻到）。
         现改为沿祖先链向上找（最多 8 层）；Adornee 留空的 SurfaceGui 用"挂载部件"
         判断归属，避免把自己角色的名牌也翻掉。
         真机验证：嵌套 1 层 / 2 层的 SurfaceGui、BillboardGui 面板共 12 条文本全部译成中文。
     [2] 修复（真机发现：浮窗出现重复行、同一条消息被反复送翻译）
         聊天窗口那一行其实是"富文本标签 + 玩家名:"的整行标记，被游戏重渲染后
         缓存 key 变了 → 同一条消息被当成新消息又请求一次。
         现新增：① 还原纯文本（去标签、去玩家名前缀）再查一次缓存；
         ② 同一 key 在翻译途中不重复排队（这批结束才放行）；
         ③ 浮窗连续重复行不堆叠、译文=原文不显示；
         ④ 就地改写时只替换正文，保留玩家名与颜色标记。
         真机验证：同一条聊天被抓到 2 次只发 1 次请求，浮窗只留 1 行。
     [3] 新增（玩家要求）：聊天浮窗可自定义
         宽 / 高 / 字号 / 背景透明度 / 位置全部可调，拖动标题栏后位置自动记住（落盘）；
         小 / 中 / 大 / 超大 四个尺寸预设（只是把上面几个数值改成预设值，不锁功能，可再手改）；
         一键"重置浮窗位置和大小"；浮窗内 A- / A+ 可快速调字号。
     [4] 修复：聊天窗口自带的图标文字（three-dots-horizontal / microphone 等）不再被翻译。
     [5] 修复：真机截图发现 💬、✕ 字符在 Roblox 的 Gotham 字体下会显示成"方框"
         → 换成真机能显示的文案与「×」。
     验证：luau-compile 0 错误；模拟环境 75 项断言全过（完整环境 + 精简注入器环境各 75/0）；
           luau-analyze 无新增告警类型；Roblox Studio 真机 + 真实 DeepSeek API 实跑通过。
]]
--[[ Roblox 翻译脚本 v1.8 · 美化 + 修复版
     ★ 本版三大块改动：
     [1] 真机验证暴露的致命问题：整份脚本所有代码都挤在同一个函数里，
         局部变量超过 Luau 的 200 个上限 → 在真实 Luau 编译器下直接编译失败。
         现已把 100+ 个顶层函数收进函数表 F，寄存器占用降到 ~130 个。
     [2] 玩家反馈的冲突：性能档位会覆盖玩家自己设置的"拖动 FPS"
         → 预设只改性能参数（扫描/批处理/并发/3D扫描），外观设置一律不碰；
            并新增"一键撤销上次套用"（快照可跨注入保存）。
         同时修复：按游戏隔离配置会把 API Key 也隔离掉（换游戏要重填 Key）
         → Key/模型等共享项永远走全局配置。
