    -- 按一下立刻补扫当前画面，用来填"扫描间隔（5~300 秒）"之间的空档。
    SCAN_HOTKEY_ENABLED = false, SCAN_HOTKEY_KEY = "G",
    PANEL_OPACITY = 0.92, CORE_BTN_SIZE = 46,
