    --   开启后额外重试次数限制在总请求的 ≤5%，防止费用/延迟失控。
    REPAIR_EXTRA_ENABLED = false,
    -- ★ v2.35 新增：思考模式。★ 用户决定（2026-10-29）：**默认关闭**（更慢、更费 token），
    --   想要更准可去性能页自己打开；强度默认仍是 high。
    -- thinking.type：on = "enabled"，off = "disabled"
    THINKING_ENABLED = false,
    -- 思考强度。官方允许的取值（文档原文）：
    --   minimal / low / medium / high / xhigh / max / ultra
    -- 官方映射表（请求传入 → 实际生效）：
    --   minimal→low   low→low   medium→high   high→high   xhigh→high   max→max   ultra→max
    -- 即实际只有三档 low / high / max，其余都是别名。
    THINKING_EFFORT = "high",
    -- 思考模式下是否省略 temperature（以及 presence/frequency_penalty 这类采样参数）。
    -- ★ 更正：原先我写"传了会报错"，那是**错的**。官方文档明确说
    --   "设置参数不会报错，但也不会生效"。
    --   所以这里省略只是为了少传无用字段，**不是为了避免报错**；
    --   关掉它把 temperature 照常发出去，也不会出错（只是不生效）。
    THINKING_OMIT_TEMPERATURE = true,
    -- ★ v2.35 新增：top_p。官方文档：
    --   · 仅在**思考模式**下生效，有效范围 0.95–1.0，低于 0.95 会按 0.95 处理
    --   · 非思考模式下该参数**恒为 1.0**，传入的值会被忽略
    --   默认 1.0 = 不改动模型输出分布。
    TOP_P = 1.0,
    -- ★ v2.35 新增、v2.36 改默认值：聊天气泡的内边距系数（配置页有滑杆，实时可调）。
    -- 越小气泡框越贴着文字；1.0 = 旧算法的一套留白。默认 0.8。
    BUBBLE_PAD_SCALE = 0.8,
    -- ★ v2.35 新增、v2.36 改默认值：译文在气泡里的**字号倍率**（配置页滑杆，实时可调）。
    -- ★ v2.36 说明：气泡尺寸算法重写之后，框会**自动贴合译文**（短句收窄、长句放宽），
    --   不再需要"把字放大去填满框"来遮丑，所以默认从 1.3 改成 **1.0（保持游戏原字号）**。
    --   它现在的语义是纯粹的"上限倍率"：>1 允许放大（放不下会自动退回），<1 只缩不放。
    BUBBLE_FONT_SCALE = 1.0,
    AUTO_SAVE_INTERVAL = 30, BLACKLIST_TTL_DAYS = 30,
    PER_PLACE_CONFIG = false,            -- ★ 新增：按游戏隔离配置（默认关闭）
    RESTORE_ON_UNLOAD = false,           -- ★ 新增：卸载脚本时还原原文
    SCAN_PROMPTS = true,                 -- ★ 新增：扫描 ProximityPrompt 文本
    SHOW_USAGE_STATS = false,            -- ★ v2.22 恢复（玩家："我是说让你修复"）：状态页显示 token / KV 缓存统计
    HISTORY_LIMIT = 2000,                -- ★ 改（玩家反馈）：历史从 200 条放宽到 2000 条（和缓存规模匹配）
    PRESET_BACKUP = "",                  -- ★ 新增：上一次套用性能档位前的参数快照（用于撤销）
    ACTIVE_PRESET = "",                  -- ★ 新增：当前生效的档位（""=自定义；手动改参数会被清空）
    THEME_ACCENT = "青绿",               -- 默认强调色；已保存的玩家选择不变
    -- ★ v2.39.8：维护者要求默认开启（拨动开关即生效，无二次确认）。
    -- 它仍是全脚本唯一会改变"客户端属性写入路径"的机制（元表是全体 Instance 共享的）；
    -- 关闭开关会立刻还原元表并核验。若执行器缺少必需函数或多次启用失败，会自动关闭并标红。
    API_HOOK_ENABLED = true,
}
local config = {}
for k, v in pairs(DEFAULT_CONFIG) do config[k] = type(v) == "table" and {} or v end
F.config_ref = config
F.default_config = DEFAULT_CONFIG   -- 供路径迁移判断"这份配置是不是全默认的模板"

