        .. "新消息走 AI 翻译后写回原生聊天框与浮窗；同一句再次出现仍会重新请求（聊天译文不落盘）。")
    -- ★ v2.36 改写：气泡尺寸算法重写后，框会**自动贴合译文**，这个滑杆不再用来"遮丑"，
